""" File generated by Antropic's Claude model Opus 5.5.

    RDP

Ramer–Douglas–Peucker (RDP) polyline simplification, aimed at plotting long
simulation trajectories with far fewer points and no visible difference.

Entry points
- `rdp_indices(x, y, ε)`         2-D points, tolerance `ε` in data units.
- `rdp_indices(P, ε)`            N-D points (columns of `P`), Euclidean metric.
- `rdp_plot_indices(x, y; ...)`  tolerance in *plot units* (pixels or pt):
                                 coordinates are first mapped to the drawing area.
- `rdp_plot_indices(t, Y; ...)`  several series (columns of `Y`) sharing `t`:
                                 one common index set, tolerance met by every series
                                 (`joint=true`), or one index set per series (`joint=false`).
- `rdp_plot(x, y; ...)`, `rdp_plot(t, Y; ...)` return the reduced data directly.
- `rdp_sol(sol; idxs, joint, ...)` / `rdp_sol_indices(sol; ...)`
                                 DifferentialEquations.jl solutions: all states jointly,
                                 selected states, observables `(u, t) -> …`, or a phase
                                 portrait `idxs = (i, j)`; optional dense interpolation.

All functions return (or use) sorted indices into the original data, first and
last points of every finite run always included.

Guarantee (per maximal run of finite points, in the coordinates where ε is
measured). Let i₁ < … < i_K be the kept indices of the run and σₖ = [p_{iₖ}, p_{iₖ₊₁}].
(i) Every discarded p_j with iₖ < j < iₖ₊₁ satisfies dist(p_j, σₖ) ≤ ε: the pairs
    (a, b) that are never split tile the run and are exactly consecutive kept
    indices, and a pair is left unsplit only if all its interior points are ≤ ε
    from its segment.
(ii) Hence the Hausdorff distance between the original polyline P and the
    simplified polyline S is ≤ ε.  P ⊂ S ⊕ ε: each original edge has both
    endpoints within ε of some σₖ and x ↦ dist(x, σₖ) is convex.  S ⊂ P ⊕ ε: the
    metric projection π onto the convex set σₖ is continuous (1-Lipschitz; see
    Bauschke & Combettes, *Convex Analysis and Monotone Operator Theory in
    Hilbert Spaces*, Prop. 4.16), so π maps the original sub-path from p_{iₖ} to
    p_{iₖ₊₁} onto all of σₖ (intermediate value theorem), and each q = π(γ(s))
    satisfies |γ(s) − q| = dist(γ(s), σₖ) ≤ ε.
With `rdp_plot_indices` the metric is the drawing-area one, so "ε = 0.5 px" means
the simplified curve never departs from the true one by more than half a pixel.

Non-finite points (NaN/±Inf, or non-positive values on a log axis) split the
data into independent runs and are themselves kept, so line breaks survive.
Runs can also be cut explicitly (`breaks`), or at every jump of a hybrid
trajectory (`keep_jumps=true`: consecutive samples with equal abscissa), so
reset instants are kept exactly and each flow interval is simplified alone.

Cost: O(n log n) typical, O(n²) worst case (very unbalanced splits). The
implementation is iterative (explicit stack), so there is no recursion-depth limit.

References
- U. Ramer, "An iterative procedure for the polygonal approximation of plane
  curves", Computer Graphics and Image Processing 1(3):244–256, 1972.
- D. H. Douglas, T. K. Peucker, "Algorithms for the reduction of the number of
  points required to represent a digitized line or its caricature",
  Cartographica 10(2):112–122, 1973.
"""
module RDP

export rdp_indices, rdp_plot_indices, rdp_plot, rdp_sol, rdp_sol_indices

# ---------------------------------------------------------------------------
# Geometry
# ---------------------------------------------------------------------------

# Segment data (ax, ay, dx, dy, |d|²) with d = b − a.
@inline function _seg2(ax::Float64, ay::Float64, bx::Float64, by::Float64)
    dx = bx - ax
    dy = by - ay
    return (ax, ay, dx, dy, dx * dx + dy * dy)
end

# Squared Euclidean distance from (px, py) to the closed segment `s`.
@inline function _segdist2(px::Float64, py::Float64, s::NTuple{5,Float64})
    ax, ay, dx, dy, L2 = s
    wx = px - ax
    wy = py - ay
    τ = wx * dx + wy * dy               # = |d|² × (projection parameter)
    if L2 == 0.0 || τ <= 0.0            # degenerate segment, or closest to a
        return wx * wx + wy * wy
    elseif τ >= L2                      # closest to b
        ex = wx - dx
        ey = wy - dy
        return ex * ex + ey * ey
    else                                # interior: |w × d|² / |d|²
        c = wx * dy - wy * dx
        return c * c / L2
    end
end

# Squared Euclidean distance from column i of P to the segment [P[:,a], P[:,b]].
@inline function _segdist2_nd(P::AbstractMatrix, i::Int, a::Int, b::Int)
    L2 = 0.0
    τ = 0.0
    @inbounds for k in axes(P, 1)
        dk = Float64(P[k, b]) - Float64(P[k, a])
        wk = Float64(P[k, i]) - Float64(P[k, a])
        L2 += dk * dk
        τ += wk * dk
    end
    λ = (L2 == 0.0 || τ <= 0.0) ? 0.0 : (τ >= L2 ? 1.0 : τ / L2)
    s = 0.0
    @inbounds for k in axes(P, 1)
        ak = Float64(P[k, a])
        rk = Float64(P[k, i]) - (ak + λ * (Float64(P[k, b]) - ak))
        s += rk * rk
    end
    return s
end

# ---------------------------------------------------------------------------
# Core (metric-agnostic)
# ---------------------------------------------------------------------------
#   prep(a, b)   -> segment data for the pair (a, b)
#   dist2(s, i)  -> squared distance of point i to segment data s

function _rdp_run!(keep::BitVector, prep::F, dist2::G, lo::Int, hi::Int,
    ε2::Float64, stack::Vector{Tuple{Int,Int}}) where {F,G}
    keep[lo] = true
    keep[hi] = true
    hi - lo < 2 && return nothing
    empty!(stack)
    push!(stack, (lo, hi))
    while !isempty(stack)
        a, b = pop!(stack)
        seg = prep(a, b)
        dmax = 0.0
        imax = 0
        for i in (a+1):(b-1)
            d = dist2(seg, i)
            if d > dmax
                dmax = d
                imax = i
            end
        end
        if dmax > ε2
            keep[imax] = true
            imax - a >= 2 && push!(stack, (a, imax))
            b - imax >= 2 && push!(stack, (imax, b))
        end
    end
    return nothing
end

# brk[j] == true  ⇒  the polyline is cut between j and j+1 (both kept).
# `breaks` is either a collection of indices or a Bool mask of length n-1.
# Always returns a fresh BitVector.
function _break_mask(breaks, n::Int)
    brk = falses(max(n - 1, 0))
    for j in breaks
        1 <= j < n || throw(ArgumentError("break index $j outside 1:$(n-1)"))
        brk[j] = true
    end
    return brk
end

function _break_mask(breaks::AbstractVector{Bool}, n::Int)
    length(breaks) == max(n - 1, 0) ||
        throw(DimensionMismatch("a Bool `breaks` mask must have length n - 1 = $(n - 1)"))
    brk = falses(max(n - 1, 0))
    brk .= breaks
    return brk
end

# Mark j with x[j] == x[j+1]: pre/post-jump samples of a hybrid trajectory.
function _mark_jumps!(brk::BitVector, x::AbstractVector)
    for j in 1:(length(x)-1)
        x[j] == x[j+1] && (brk[j] = true)
    end
    return brk
end

function _rdp_mask(n::Int, valid::V, prep::F, dist2::G, ε::Real,
    brk::BitVector=falses(max(n - 1, 0))) where {V,F,G}
    ε >= 0 || throw(ArgumentError("tolerance must be ≥ 0, got $ε"))
    ε2 = Float64(ε)^2
    keep = falses(n)
    stack = Tuple{Int,Int}[]
    i = 1
    while i <= n
        if !valid(i)                    # keep NaN/Inf markers (line breaks)
            keep[i] = true
            i += 1
            continue
        end
        j = i
        while j < n && !brk[j] && valid(j + 1)
            j += 1
        end
        _rdp_run!(keep, prep, dist2, i, j, ε2, stack)
        i = j + 1
    end
    return keep
end

# ---------------------------------------------------------------------------
# Tolerance in data units
# ---------------------------------------------------------------------------

"""
    rdp_indices(x, y, ε) -> Vector{Int}

Indices of the points kept by RDP for the planar polyline `(x[i], y[i])`, with
tolerance `ε ≥ 0` in the units of the data. Distances are to the closed segment
(not the infinite line), so non-monotone curves such as phase portraits are
handled correctly.

Keyword `breaks`: indices `j` at which the polyline is cut between `j` and
`j+1` (both kept, pieces simplified independently), e.g. the jump instants of a
hybrid trajectory; alternatively a Bool mask of length `n - 1`.

Note: `x` and `y` usually have very different scales in a time plot; prefer
[`rdp_plot_indices`](@ref), which measures `ε` in the drawing area.
"""
function rdp_indices(x::AbstractVector{<:Real}, y::AbstractVector{<:Real}, ε::Real;
    breaks=())
    Base.require_one_based_indexing(x, y)
    n = length(x)
    length(y) == n || throw(DimensionMismatch("x and y must have the same length"))
    valid = i -> @inbounds(isfinite(x[i]) && isfinite(y[i]))
    prep = (a, b) -> @inbounds(_seg2(Float64(x[a]), Float64(y[a]), Float64(x[b]), Float64(y[b])))
    dist2 = (s, i) -> @inbounds(_segdist2(Float64(x[i]), Float64(y[i]), s))
    return findall(_rdp_mask(n, valid, prep, dist2, ε, _break_mask(breaks, n)))
end

"""
    rdp_indices(P::AbstractMatrix, ε; breaks=()) -> Vector{Int}

N-dimensional version: the points are the columns of `P` (`d × n`), distances
are Euclidean point-to-segment distances in ℝᵈ (e.g. a 3-D phase portrait).
"""
function rdp_indices(P::AbstractMatrix{<:Real}, ε::Real; breaks=())
    Base.require_one_based_indexing(P)
    n = size(P, 2)
    valid = i -> begin
        @inbounds for k in axes(P, 1)
            isfinite(P[k, i]) || return false
        end
        return true
    end
    prep = (a, b) -> (a, b)
    dist2 = (s, i) -> _segdist2_nd(P, i, s[1], s[2])
    return findall(_rdp_mask(n, valid, prep, dist2, ε, _break_mask(breaks, n)))
end

# ---------------------------------------------------------------------------
# Tolerance in plot units
# ---------------------------------------------------------------------------

function _scale_fun(s::Symbol)
    s === :identity && return identity
    s === :log10 && return v -> v > 0 ? log10(v) : NaN
    s === :log2 && return v -> v > 0 ? log2(v) : NaN
    (s === :ln || s === :log) && return v -> v > 0 ? log(v) : NaN
    throw(ArgumentError("unsupported axis scale :$s (use :identity, :log10, :log2 or :ln)"))
end

# Axis range in transformed units: from `lims` (data units) or from the finite data.
function _axis_range(v, f::F, lims) where {F}
    if lims === nothing || lims === :auto
        lo, hi = Inf, -Inf
        for vi in v
            u = f(Float64(vi))
            if isfinite(u)
                lo = min(lo, u)
                hi = max(hi, u)
            end
        end
        return lo <= hi ? (lo, hi) : (0.0, 1.0)   # no finite data at all
    else
        lo = f(Float64(lims[1]))
        hi = f(Float64(lims[2]))
        (isfinite(lo) && isfinite(hi)) ||
            throw(ArgumentError("axis limits $lims are not valid for this axis scale"))
        return (lo, hi)
    end
end

# out[i] = position of v[i] along an axis of length `len` (pixels, pt, ...).
function _to_plot!(out::AbstractVector{Float64}, v::AbstractVector, f::F,
    r::Tuple{Float64,Float64}, len::Real) where {F}
    lo, hi = r
    span = abs(hi - lo)
    κ = Float64(len) / (span > 0 ? span : 1.0)
    @inbounds for i in eachindex(out, v)
        out[i] = (f(Float64(v[i])) - lo) * κ
    end
    return out
end

"""
    rdp_plot_indices(x, y; tol=0.5, figsize=(600, 400), xlims=nothing, ylims=nothing,
                     xscale=:identity, yscale=:identity) -> Vector{Int}

RDP with the tolerance expressed in the drawing area: the data are mapped to a
`figsize[1] × figsize[2]` rectangle (same units as `tol`, e.g. pixels, or pt
for a PDF/TikZ figure) using the axis limits and scales, then simplified with
`ε = tol`. The simplified curve is within `tol` (Hausdorff) of the original one
*as drawn*.

- `xlims`, `ylims`: `(lo, hi)` in data units, or `nothing` for the data extent.
- `xscale`, `yscale`: `:identity`, `:log10`, `:log2`, `:ln` (Plots.jl names).
  Non-positive values on a log axis are treated like NaN.
- `keep_jumps=true`: consecutive samples with the same abscissa (the pre- and
  post-reset states that DifferentialEquations.jl saves at a callback) are
  always kept, and each flow interval is simplified on its own. Without it,
  jumps are still drawn within `tol`, but the exact reset samples may be
  replaced by a neighbour.
- `breaks`: extra cuts, as in [`rdp_indices`](@ref) (indices or a Bool mask).

Using the whole figure size is conservative: the actual axes area is smaller,
so actual deviations are below `tol`. For a subplot layout, pass the size of
one subplot.
"""
function rdp_plot_indices(x::AbstractVector{<:Real}, y::AbstractVector{<:Real};
    tol::Real=0.5, figsize=(600, 400),
    xlims=nothing, ylims=nothing,
    xscale::Symbol=:identity, yscale::Symbol=:identity,
    keep_jumps::Bool=false, breaks=())
    Base.require_one_based_indexing(x, y)
    n = length(x)
    length(y) == n || throw(DimensionMismatch("x and y must have the same length"))
    fx = _scale_fun(xscale)
    fy = _scale_fun(yscale)
    X = _to_plot!(Vector{Float64}(undef, n), x, fx, _axis_range(x, fx, xlims), figsize[1])
    Y = _to_plot!(Vector{Float64}(undef, n), y, fy, _axis_range(y, fy, ylims), figsize[2])
    brk = _break_mask(breaks, n)
    keep_jumps && _mark_jumps!(brk, x)
    return rdp_indices(X, Y, tol; breaks=brk)
end

"""
    rdp_plot_indices(t, Y::AbstractMatrix; joint=true, shared_ylims=true, kwargs...)

Several series `Y[:, k]` sampled at the same `t`.

- `joint=true` → `Vector{Int}`: one common index set. A point is discarded only
  if it is within `tol` of the kept segment *for every series*, so the indices
  serve all columns at once (`plot(t[idx], Y[idx, :])`, or a single time column
  in a data file).
- `joint=false` → `Vector{Vector{Int}}`: each series simplified on its own
  (fewest points per series; `plot([t[i] for i in K], [Y[i, k] for (k, i) in enumerate(K)])`).

`shared_ylims=true` (one axis for all series, as in `plot(t, Y)`) uses a common
y-range; `false` maps each series to its own range (one subplot per series; then
`figsize` should be the size of one subplot). Other keywords as for the 2-D method.
"""
function rdp_plot_indices(t::AbstractVector{<:Real}, Y::AbstractMatrix{<:Real};
    tol::Real=0.5, figsize=(600, 400),
    xlims=nothing, ylims=nothing,
    xscale::Symbol=:identity, yscale::Symbol=:identity,
    shared_ylims::Bool=true, joint::Bool=true,
    keep_jumps::Bool=false, breaks=())
    Base.require_one_based_indexing(t, Y)
    n, m = size(Y)
    length(t) == n || throw(DimensionMismatch("length(t) must equal size(Y, 1)"))
    fx = _scale_fun(xscale)
    fy = _scale_fun(yscale)
    X = _to_plot!(Vector{Float64}(undef, n), t, fx, _axis_range(t, fx, xlims), figsize[1])
    Yp = Matrix{Float64}(undef, m, n)          # series-major storage: Yp[k, i]
    common = shared_ylims ? _axis_range(Y, fy, ylims) : (0.0, 1.0)
    for k in 1:m
        yk = view(Y, :, k)
        r = shared_ylims ? common : _axis_range(yk, fy, ylims)
        _to_plot!(view(Yp, k, :), yk, fy, r, figsize[2])
    end
    brk = _break_mask(breaks, n)
    keep_jumps && _mark_jumps!(brk, t)
    joint && return _rdp_joint(X, Yp, tol, brk)
    return [rdp_indices(X, Yp[k, :], tol; breaks=brk) for k in 1:m]
end

function _rdp_joint(X::Vector{Float64}, Yp::Matrix{Float64}, ε::Real, brk::BitVector)
    m, n = size(Yp)
    valid = i -> begin
        @inbounds isfinite(X[i]) || return false
        @inbounds for k in 1:m
            isfinite(Yp[k, i]) || return false
        end
        return true
    end
    prep = (a, b) -> (a, b)
    dist2 = (s, i) -> begin
        a, b = s
        d = 0.0
        @inbounds begin
            ax = X[a]
            bx = X[b]
            px = X[i]
            for k in 1:m
                d = max(d, _segdist2(px, Yp[k, i], _seg2(ax, Yp[k, a], bx, Yp[k, b])))
            end
        end
        return d
    end
    return findall(_rdp_mask(n, valid, prep, dist2, ε, brk))
end

"""
    rdp_plot(x, y; kwargs...) -> (x_reduced, y_reduced)
    rdp_plot(t, Y::AbstractMatrix; joint=true, kwargs...)

Convenience wrappers around [`rdp_plot_indices`](@ref) returning the reduced
data. For a matrix: `joint=true` gives `(t_red, Y_red)` (vector, matrix);
`joint=false` gives `(ts, ys)`, two vectors of vectors (one per series), which
`Plots.plot(ts, ys)` draws as separate series.
"""
function rdp_plot(x::AbstractVector, y::AbstractVector; kwargs...)
    idx = rdp_plot_indices(x, y; kwargs...)
    return x[idx], y[idx]
end

function rdp_plot(t::AbstractVector, Y::AbstractMatrix; joint::Bool=true, kwargs...)
    K = rdp_plot_indices(t, Y; joint=joint, kwargs...)
    joint && return t[K], Y[K, :]
    return [t[k] for k in K], [Y[k, c] for (c, k) in enumerate(K)]
end

# ---------------------------------------------------------------------------
# DifferentialEquations.jl solutions
# ---------------------------------------------------------------------------
# Duck-typed, no SciML dependency: `sol` needs fields `sol.t` (increasing) and
# `sol.u` (states: vectors, ArrayPartitions, scalars, ... anything with u[k]),
# and must be callable as `sol(τ)` when `dense > 0`. Works for ODESolution,
# SDE/DDE solutions, DiffEqArray, etc.

_nstates(sol) = isempty(sol.u) ? 0 : length(first(sol.u))

# One plotted quantity: 0 → time, k::Integer → state k, anything else f → f(u, t).
_quantity(spec::Integer, u, t) = spec == 0 ? t : u[spec]
_quantity(f, u, t) = f(u, t)
_column(spec, ts, us) = Float64[_quantity(spec, u, τ) for (τ, u) in zip(ts, us)]

function _specs(idxs, sol)
    idxs === nothing && return collect(1:_nstates(sol))
    idxs isa AbstractVector && return collect(idxs)
    return [idxs]
end

# Saved samples in the window `tspan` plus one neighbour on each side, so the
# drawn line reaches the window edges.
function _saved_range(t::AbstractVector, tspan)
    n = length(t)
    tspan === nothing && return 1:n
    t0, t1 = tspan
    t0 <= t1 || throw(ArgumentError("tspan must satisfy t0 ≤ t1"))
    lo = max(searchsortedfirst(t, t0) - 1, 1)
    hi = min(searchsortedlast(t, t1) + 1, n)
    return lo:hi
end

# Saved samples in `r`, plus `npts` uniformly spaced samples of the interpolant
# `sol(τ)` placed strictly inside the flow intervals (never at a saved time, so
# duplicated jump samples stay untouched and in order).
function _dense_samples(sol, r::AbstractUnitRange, npts::Integer)
    t = sol.t
    U = eltype(sol.u)
    isempty(r) && return Float64[], U[]
    grid = range(Float64(t[first(r)]), Float64(t[last(r)]); length=max(npts, 2))
    ts = Float64[]
    us = U[]
    sizehint!(ts, length(r) + length(grid))
    sizehint!(us, length(r) + length(grid))
    g = 1
    tprev = -Inf
    for j in r
        tj = Float64(t[j])
        while g <= length(grid) && grid[g] < tj
            τ = grid[g]
            if τ > tprev
                push!(ts, τ)
                push!(us, sol(τ))
            end
            g += 1
        end
        push!(ts, tj)
        push!(us, sol.u[j])
        tprev = tj
    end
    return ts, us
end

# Common engine. Returns (mode, r, a, b, K):
#   mode = :phase → a = x values, b = y values, K::Vector{Int}
#   mode = :time  → a = t, b = n × m matrix, K::Vector{Int} (joint) or Vector{Vector{Int}}
# K indexes the sample sequence (saved samples in r, plus dense ones if any).
function _sol_reduce(sol, idxs, joint::Bool, keep_jumps::Bool, dense::Integer,
    tspan, xlims, shared_ylims::Bool; kwargs...)
    dense >= 0 || throw(ArgumentError("dense must be ≥ 0"))
    r = _saved_range(sol.t, tspan)
    ts, us = dense > 0 ? _dense_samples(sol, r, dense) : (view(sol.t, r), view(sol.u, r))
    brk = falses(max(length(ts) - 1, 0))
    keep_jumps && _mark_jumps!(brk, ts)       # jumps are detected in *time*
    if idxs isa Tuple                          # phase portrait, DiffEq convention
        length(idxs) == 2 ||
            throw(ArgumentError("a phase-space idxs must be a 2-tuple (i, j); 0 stands for time"))
        x = _column(idxs[1], ts, us)
        y = _column(idxs[2], ts, us)
        K = rdp_plot_indices(x, y; breaks=brk, xlims=xlims, kwargs...)
        return :phase, r, x, y, K
    end
    specs = _specs(idxs, sol)
    t = _column(0, ts, us)
    Y = Matrix{Float64}(undef, length(t), length(specs))
    for (c, s) in enumerate(specs)
        Y[:, c] = _column(s, ts, us)
    end
    xl = (xlims === nothing && tspan !== nothing) ? tspan : xlims
    K = rdp_plot_indices(t, Y; joint=joint, shared_ylims=shared_ylims,
        breaks=brk, xlims=xl, kwargs...)
    return :time, r, t, Y, K
end

"""
    rdp_sol(sol; idxs=nothing, joint=true, keep_jumps=true, dense=0, tspan=nothing,
            shared_ylims=true, tol=0.5, figsize=(600, 400), kwargs...)

Reduced plotting data from a DifferentialEquations.jl solution (`plot(rdp_sol(sol)...)`).

What is plotted (`idxs`, same convention as the DiffEq plot recipe):
- `nothing`: all states vs time.
- `k`: state `k` only → `(t, u_k)`; the simplification is optimised for that state alone.
- `[i, j, …]`: those states vs time. Elements may also be functions `(u, t) -> value`
  (an output `y = C*u`, a Lyapunov function, …).
- `(i, j)`: phase portrait `u_i` vs `u_j` → `(x, y)`; `0` stands for time, so
  `(0, k)` is the same as `k`.

Several quantities vs time:
- `joint=true`  → `(t, U)`: one common set of time instants, `U` is `n_kept × m`,
  every column within `tol`. Use `plot(t, U)` / `plot(t, U; layout = (m, 1))`.
- `joint=false` → `(ts, ys)`: vectors of vectors, each quantity optimised on its
  own (fewer points in total). Use `plot(ts, ys)`.
- `shared_ylims=true` matches one common axis (as `plot(sol)`); use `false`
  with a layout of one subplot per quantity, and `figsize` = size of one subplot.

Other options:
- `keep_jumps=true`: samples saved twice at the same time (pre/post event of a
  callback) are always kept and each flow interval is simplified separately.
- `dense=N` (N ≥ 2): add N uniformly spaced samples of the interpolant `sol(τ)`
  before simplifying, so that curves between sparse adaptive steps are drawn
  smoothly (like `plot(sol)` does). Only meaningful for solutions with dense
  output (default `solve` without `saveat`).
- `tspan=(t0, t1)`: only this time window (plus one sample on each side);
  it is also used as `xlims` for plots vs time unless `xlims` is given.
- `tol`, `figsize`, `xlims`, `ylims`, `xscale`, `yscale`: as in [`rdp_plot_indices`](@ref).
"""
function rdp_sol(sol; idxs=nothing, joint::Bool=true, keep_jumps::Bool=true,
    dense::Integer=0, tspan=nothing, xlims=nothing,
    shared_ylims::Bool=true, kwargs...)
    mode, _, a, b, K = _sol_reduce(sol, idxs, joint, keep_jumps, dense, tspan, xlims,
        shared_ylims; kwargs...)
    mode === :phase && return a[K], b[K]
    single = size(b, 2) == 1
    if joint
        return single ? (a[K], b[K, 1]) : (a[K], b[K, :])
    else
        ts = [a[k] for k in K]
        ys = [b[k, c] for (c, k) in enumerate(K)]
        return single ? (ts[1], ys[1]) : (ts, ys)
    end
end

"""
    rdp_sol_indices(sol; idxs=nothing, joint=true, keep_jumps=true, tspan=nothing, kwargs...)

Same as [`rdp_sol`](@ref) (without `dense`) but returns indices into `sol.t`
/ `sol.u`: a `Vector{Int}`, or with `joint=false` one `Vector{Int}` per
quantity. Useful to thin other arrays saved on the same grid (e.g. a `SavingCallback`).
"""
function rdp_sol_indices(sol; idxs=nothing, joint::Bool=true, keep_jumps::Bool=true,
    tspan=nothing, xlims=nothing, shared_ylims::Bool=true,
    kwargs...)
    _, r, _, _, K = _sol_reduce(sol, idxs, joint, keep_jumps, 0, tspan, xlims,
        shared_ylims; kwargs...)
    off = first(r) - 1
    return eltype(K) <: Integer ? K .+ off : [k .+ off for k in K]
end

end # module